auto func (auto value){  
    int count = 0;  
    for (int i = 0; i < value.size(); i++) {  
        if (value[i] > 0) {  
            count++;  
        }  
    }  
    return count;  
}

auto func (auto value){  
    int count = 0;  
    for (const auto& item : value) {  
        if (item) count++;  
    }  
    return count;  
}
